import{_ as l,C as e,o as r,c as o,j as a,a as p,E as s,a3 as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"坐忘论·坐忘枢翼","description":"坐忘论附篇精读：三戒为枢，定慧为翼；五时七候总摄修道进程，并含松紧尺度与安全边界。","frontmatter":{"title":"坐忘论·坐忘枢翼","description":"坐忘论附篇精读：三戒为枢，定慧为翼；五时七候总摄修道进程，并含松紧尺度与安全边界。","category":"guide","aliases":["坐忘枢翼","坐忘论枢翼","坐忘论精读之九"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-08.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-08.md","lastUpdated":1789714390000}'),g={name:"daoism/daoist-classics/zuowang-lun/chapter-08.md"};function c(b,t,u,m,x,v){const i=e("DaoReadingPrelude"),n=e("DaoTextReading"),d=e("DaoKeywordCards");return r(),o("div",null,[t[0]||(t[0]=a("h1",{id:"坐忘论·坐忘枢翼",tabindex:"-1"},[p("坐忘论·坐忘枢翼 "),a("a",{class:"header-anchor",href:"#坐忘论·坐忘枢翼","aria-label":'Permalink to "坐忘论·坐忘枢翼"'},"​")],-1)),s(i,{title:"唯灭动心，不灭照心",summary:"「枢」是枢纽、关键，「翼」是辅翼、展开。本篇把前七篇浓缩为三戒（简缘、无欲、静心），又以「心有五时、身有七候」描述修行由心渐静、定慧相生，直至炼神合道的完整进程。它回答的是七篇之外那些实操问题：收心怎样掌握松紧？如何判断是真定还是强制压心？定中出现异象怎么办？",points:[{label:"立三戒",text:"简缘、无欲、静心——外简其缘，内寡其欲，中心常静。"},{label:"明总诀",text:"唯灭动心，不灭照心；制而无著，放而不逸。"},{label:"定尺度",text:"以无事为真定，以有事为应迹；束心太急，急则成病。"}],hint:"篇末「延数千岁」「炼形为气」等属道教神仙学的宗教性身体观。精读时应区分其原典宗教意义，与今天可以直接实行的调心原则。"}),t[1]||(t[1]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[p("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),t[2]||(t[2]=a("p",null,[a("strong",null,"一、坐忘的基本方法")],-1)),s(n,{paragraphs:["夫欲修道成真，先去邪僻之行，外事都绝，无以干心，然后端坐，内观正觉。","觉一念起，即须除灭，随起随制，务令安静。","其次，虽非的有贪著，浮游乱想，亦尽灭除，昼夜勤行，须臾不替。","唯灭动心，不灭照心，但冥虚心，不冥有心，不依一物，而心常住。"]}),t[3]||(t[3]=a("p",null,[a("strong",null,"二、为何此法难信、难行")],-1)),s(n,{paragraphs:["此法玄妙利益甚深，自非夙有道缘、信心无二者，莫能信重。","虽知诵读其文，仍须辩识真伪，所以者何？声色昏心，邪佞惑耳，人我成性，自是病深，心与道隔，理难晓悟。"]}),t[4]||(t[4]=a("p",null,[a("strong",null,"三、三戒与调心的松紧尺度")],-1)),s(n,{paragraphs:["若有心归至道，深生信慕，先受三戒，依戒修行，在终如始，乃得真道。其三戒者，一曰简缘，二曰无欲，三曰静心。","勤行此三戒，而无懈退者，则无心求道而道自来。经云：人能虚心无为，非欲于道，道自归之。","由此言之，简要之法，实可信哉，实可贵哉。然则凡心躁竞，其来固久，依戒息心，其事甚难。","或息之而不得，暂得而还失，去留交战，百体流汗，久久柔挺，方乃调熟。莫以暂收不得，遂废平生之业。","少得静已，则行立坐卧之时，涉事喧阓之处，皆须作意安之。有事无事，常若无心，处静处喧，其志唯一。","若束心太急，急则成病，气发狂痴，是其候也。"]}),t[5]||(t[5]=a("p",null,[a("strong",null,"四、真定的定义与动静关系")],-1)),s(n,{paragraphs:["心若不动，又须放任，宽急得中，常自调适，制而无著，放而不逸，处喧无恶，涉事无恼者，此真定也。","不以涉事无恼，故求多事，不以处喧无动，故来就喧。","以无事为真定，以有事为应迹。若水镜之为鉴，则遇物而见形。"]}),t[6]||(t[6]=a("p",null,[a("strong",null,"五、定慧关系及定中异象")],-1)),s(n,{paragraphs:["善巧方便，唯能入定，发慧迟速，则不由人。","勿于定中急急求慧，求慧则伤定，伤定则无慧。定不求慧，而慧自生，此真慧也。","慧而不用，实智若愚，益资定慧，双美无极。","若定中念想，则有多感，众邪百魅，随心应现，真人老君，神异诡怪，是其祥也。","唯定心之上，豁然无覆，定心之下，旷然无基，旧业永消，新业不造，无所缠碍，迥脱尘网，行而久之，自然得道。"]}),t[7]||(t[7]=a("p",null,[a("strong",null,"六、心有五时")],-1)),s(n,{paragraphs:["夫得道之人，心有五时，身有七候。","心有五时者，一动多静少；二动静相半；三静多动少；四无事则静，事触还动；五心与道合，触而不动。","心至此地，始得安乐，罪垢灭尽，无复烦恼。"]}),t[8]||(t[8]=a("p",null,[a("strong",null,"七、身有七候")],-1)),s(n,{paragraphs:["身有七候者，一举动顺时，容色和悦；二夙疾普消，身心轻爽；三填补夭伤，还元复命；四延数千岁，名曰仙人；五链形为气，名曰真人；六炼气成神，名曰神人；七炼神合道，名曰至人。","其于鉴力，随候益明，得至道成，慧乃圆备。","虽久学定心，身无五时七候者，促龄秽质，色谢归空，自云慧觉，复称成道，求诸通理，实所未然，可谓谬矣。"]}),t[9]||(t[9]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(d,{items:[{term:"邪僻之行",pinyin:["xié","pì","zhī","xíng"],meaning:"不正、偏僻、有害的行为（伤害他人、欺骗邪佞、贪残纵欲、以修道之名求利等）。伦理不是定外附加的规则，而是定的基础。"},{term:"无以干心",pinyin:["wú","yǐ","gān","xīn"],meaning:"干，干犯、扰动。使外在事务不再频繁侵入内心。「外事都绝」的最终目的不是绝对封闭的环境，而是使心获得不受干扰的修习条件。"},{term:"内观正觉",pinyin:["nèi","guān","zhèng","jué"],meaning:"内观，返回来观察自己的心念、情绪和执著如何生起；正觉，端正、清明、不受邪想支配的觉察（清醒/如实/正直/不随）。"},{term:"随起随制",pinyin:["suí","qǐ","suí","zhì"],meaning:"念头随时生起便随时调节。「制」不一定是强制，更接近看见、截止、不续、返回当下——重点在「觉」在「除」前。"},{term:"浮游乱想",pinyin:["fú","yóu","luàn","xiǎng"],meaning:"没有明确目的却不断漂浮迁移的念头（无目的回忆、虚构对话、随意设想）。看似无害，却使心不能稳定。"},{term:"须臾不替",pinyin:["xū","yú","bù","tì"],meaning:"顷刻也不间断。非指昼夜不眠或全天紧张监控，而是强调修习具有连续性：坐时、行时、应对事务时皆有觉察。"},{term:"唯灭动心，不灭照心",pinyin:["wéi","miè","dòng","xīn","bù","miè","zhào","xīn"],meaning:"动心是随境妄动攀缘之心，照心是清醒觉察之心。只应止息妄动，不应使觉照一并熄灭——本篇总纲之一，也是辨别真定与昏沉的根本尺度。"},{term:"冥虚心",pinyin:["míng","xū","xīn"],meaning:"「但冥虚心，不冥有心」文字古奥或涉版本问题。大意：使虚妄浮动之心沉寂，不使本有觉照之心陷入昏冥。所寂灭者虚妄攀缘，所保留者本有觉照。"},{term:"不依一物",pinyin:["bù","yī","yī","wù"],meaning:"不把任何境界当作必须攀附的固定支点（声色、呼吸感受、身体某处、空白状态、清静体验、神异景象、「我正在入定」的意识）。与【收心】「住无所有」一致。"},{term:"信心无二",pinyin:["xìn","xīn","wú","èr"],meaning:"对大道和正法的信心专一，不因暂时得失而摇摆。不意味着不能辨伪或提问——下一句恰恰说「仍须辨识真伪」：方向坚定而方法审慎。"},{term:"简缘",pinyin:["jiǎn","yuán"],meaning:"三戒之一。精简使心攀附、耗散的因缘：不以功利机心结交，不主动扩大无必要关系，必要关系做到适度而不黏著。总摄【断缘】【简事】。"},{term:"无欲",pinyin:["wú","yù"],meaning:"三戒之一。不是毁灭全部正常需要，而是不以占有为安、不把喜好当作必需、不追求声色名利与修道异能。总摄【真观】。"},{term:"静心",pinyin:["jìng","xīn"],meaning:"三戒之一。不是意识空白，而是动念能觉、觉而不随、灭动不灭照、不依一物而心常住。总摄【收心】【泰定】。"},{term:"在终如始",pinyin:["zài","zhōng","rú","shǐ"],meaning:"从开始直到最终都以同样的慎重与勤勉坚持三戒。越接近后段，越要防止因定慧所得而重新生欲。"},{term:"躁竞",pinyin:["zào","jìng"],meaning:"躁动、争竞。凡心躁竞并非一日形成，而是长期习惯的结果——所以初静时反而不适，这是正常阶段。"},{term:"柔挺",pinyin:["róu","tǐng"],meaning:"底本文字较难解，可能涉及异文。结合全文，与调柔刚强、使紧张执拗之心渐趋柔顺有关。关键在「久久」，不是一时猛烈。"},{term:"喧阓",pinyin:["xuān","huì"],meaning:"喧闹的市井、人群环境。修习渐熟后，即使处理必要事务、身处喧闹，也要有意保护心的安定。"},{term:"束心太急",pinyin:["shù","xīn","tài","jí"],meaning:"强迫自己完全无念、一念出现便严厉自责、长时间屏息紧绷、为追求定境严重减少睡眠等。本篇最重要的安全警告：急则成病。"},{term:"宽急得中",pinyin:["kuān","jí","dé","zhōng"],meaning:"调心既不能过于宽松，也不能过于急迫。不是永远固定的力度，而要根据当下散、紧、昏、明的状态随时调节。"},{term:"制而无著，放而不逸",pinyin:["zhì","ér","wú","zhuó","fàng","ér","bù","yì"],meaning:"收摄时便收摄而不执著于控制与静境；放松时便放松而不陷入散漫。收摄而不僵硬，放松而不散漫——松紧调节的最高概括。"},{term:"应迹",pinyin:["yìng","jì"],meaning:"事情到来时所作的处理，只是清静心随缘显现的应事痕迹。「以无事为真定，以有事为应迹」：清静是体，应事是用，应事结束即复归无事。"},{term:"善巧方便",pinyin:["shàn","qiǎo","fāng","biàn"],meaning:"人所能安排的入定条件：合适环境、端正坐姿、简缘减欲、调节松紧、念起不随、规律练习。人只能创造虚静清明的条件，不能直接制造本慧。"},{term:"实智若愚",pinyin:["shí","zhì","ruò","yú"],meaning:"具有真实智慧的人外表反像不逞聪明的朴拙者。非故意装傻，而是不抢先表现、不事事发表见解、不以知识建立权威。"},{term:"众邪百魅，随心应现",pinyin:["zhòng","xié","bǎi","mèi","suí","xīn","yìng","xiàn"],meaning:"各种鬼魅邪异之象随内心想念而呈现。关键在「随心」——不应立即认定为外在真实存在；即使显现的是真人、老君等神圣形象，也可能是定中想念所现。"},{term:"豁然无覆，旷然无基",pinyin:["huò","rán","wú","fù","kuàng","rán","wú","jī"],meaning:"定心之上开阔明朗，没有观念、形象与执著覆盖；定心之下广大无依，没有固定对象作为支撑。上无覆、下无基，而觉照仍然明朗——不是坠入虚无，而是无所著的清明。"},{term:"迥脱尘网",pinyin:["jiǒng","tuō","chén","wǎng"],meaning:"远离原有罗网。「尘网」不是社会本身，而是名利网、毁誉网、欲望网、人我网、自是网。"},{term:"五时",pinyin:["wǔ","shí"],meaning:"心的五个阶段：动多静少 → 动静相半 → 静多动少 → 无事则静事触还动 → 心与道合触而不动。「时」不是固定时长，而是修心进展的阶段。"},{term:"七候",pinyin:["qī","hòu"],meaning:"身的七种征候：容色和悦 → 身心轻爽 → 还元复命 → 仙人 → 真人 → 神人 → 至人。「候」是征候、表现，更鲜明地体现道教形神修炼与神仙学。"},{term:"鉴力",pinyin:["jiàn","lì"],meaning:"明镜般的照见能力：觉察念头、洞察因果、辨别真伪、由本知末。「随候益明」——随着身心转化加深，观照能力越来越清明。"},{term:"促龄秽质",pinyin:["cù","líng","huì","zhì"],meaning:"促龄，寿命短促；秽质，形质未道化。本篇以此批评只有自称慧觉而无身心实际转化的情况。现代视角下，寿命身体状况受复杂因素影响，不能据此判定修行真假。"}]}),t[10]||(t[10]=h(`<h2 id="【解读层】精读" tabindex="-1">【解读层】精读 <a class="header-anchor" href="#【解读层】精读" aria-label="Permalink to &quot;【解读层】精读&quot;">​</a></h2><h3 id="全篇结构与七层读法" tabindex="-1">全篇结构与七层读法 <a class="header-anchor" href="#全篇结构与七层读法" aria-label="Permalink to &quot;全篇结构与七层读法&quot;">​</a></h3><p>《坐忘枢翼》是七篇之后的一篇<strong>修习总纲与进阶检验表</strong>。它一方面把前七篇浓缩为三戒（简缘、无欲、静心），另一方面以「心有五时、身有七候」描述修行由心渐静、定慧相生，直至炼神合道的完整进程。</p><p>七篇主要回答「修道应当依怎样的次第展开」；本篇进一步回答：<strong>实际收心时应怎样掌握松紧？如何判断是真定还是强制压心？定中出现异象怎么办？心与身体的变化又应如何检验？</strong></p><p>全篇尤其强调四项原则：</p><blockquote><p><strong>唯灭动心，不灭照心。</strong><strong>制而无著，放而不逸。</strong><strong>以无事为真定，以有事为应迹。</strong><strong>定不求慧，而慧自生。</strong></p></blockquote><p>这些原则使「坐忘」不落入四种偏差：昏沉无知 · 紧张压抑 · 主动多事 · 急求智慧与异象。</p><table tabindex="0"><thead><tr><th>层</th><th>内容</th></tr></thead><tbody><tr><td>一 · 坐忘的基本方法</td><td>去邪行、绝外扰、端坐内观、念起即觉、灭动不灭照、不依一物而心常住</td></tr><tr><td>二 · 为何难信难行</td><td>声色昏心、邪佞惑耳、人我成性、自是病深</td></tr><tr><td>三 · 三戒与松紧尺度</td><td>简缘、无欲、静心；息心不得→暂得还失→去留交战→久久调熟；防束心过急</td></tr><tr><td>四 · 真定与动静</td><td>制而无著，放而不逸；不主动求喧求事；无事为真定，有事为应迹</td></tr><tr><td>五 · 定慧与异象</td><td>发慧不由人、急求伤定、慧而不用、定中异象不取</td></tr><tr><td>六 · 心有五时</td><td>由动多静少至触而不动</td></tr><tr><td>七 · 身有七候</td><td>由容色和悦至炼神合道</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>去邪行 → 绝外扰 → 端坐内观 → 念起即觉 → 觉而不续</span></span>
<span class="line"><span>        ↓ 只灭妄动不灭觉照；收摄而不执著，放松而不散漫</span></span>
<span class="line"><span>无事安定是体，有事随应是迹（不主动生事，也不逃避必要事务）</span></span>
<span class="line"><span>        ↓ 不可急求智慧，不可追逐异象</span></span>
<span class="line"><span>三戒 → 五时 → 七候 → 炼神合道</span></span></code></pre></div><p>（篇末「延数千岁」「炼形为气」「炼气成神」等，属道教神仙学的宗教性身体观，<strong>不能直接当作现代医学或自然科学已经验证的事实</strong>。精读时应区分其原典宗教意义与今天可直接实行的调心原则。）</p><h3 id="一、修道成真-为什么必须先去邪行" tabindex="-1">一、修道成真，为什么必须先去邪行 <a class="header-anchor" href="#一、修道成真-为什么必须先去邪行" aria-label="Permalink to &quot;一、修道成真，为什么必须先去邪行&quot;">​</a></h3><p>「欲修道成真」——「成真」不是只获得一种静坐体验，而是行为不邪、外缘减少、内心安定、定慧显发、形神逐步与道相应。<strong>因此坐忘并非脱离伦理和生活的孤立技术。</strong></p><p>「先去邪僻之行」——若外在行为仍不断制造冲突、愧疚和后果，静坐时便很难真正安心：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>行为偏曲 → 制造现实后患 → 心中反复忧惧 → 静坐也难安定</span></span></code></pre></div><p><strong>所以伦理不是定外附加的规则，而是定的基础。</strong></p><p>「外事都绝」不宜理解为废弃全部生存事务——前文已说明「事有不可废，物有不可弃者」。这里所绝的主要是非必要人事、功利攀缘、声色娱乐、名利争竞，即【断缘】与【简事】的合并表达。「无以干心」的最终目的不是形成一个绝对封闭的环境，而是<strong>使心获得不受干扰的修习条件</strong>：真正的干扰常常是事情已经过去、心仍反复思量。</p><h3 id="二、「端坐-内观正觉」" tabindex="-1">二、「端坐，内观正觉」 <a class="header-anchor" href="#二、「端坐-内观正觉」" aria-label="Permalink to &quot;二、「端坐，内观正觉」&quot;">​</a></h3><p>「端坐」——「端」包含两层：身体端正而不故意扭曲，心志端正而不求邪异体验。坐姿应稳定而不过度僵硬；若强行挺直、屏息、忍痛，反而与后文「宽急得中」相违。</p><p>「内观」——不再追逐外境，而是返回来观察自己的心念、情绪和执著如何生起：念头何时出现？因何境界而起？是否附带爱恶？能否在初起时停止续接？</p><p>「正觉」——这里不是直接宣称已达到某种觉悟，而是端正、清明、不受邪想支配的觉察：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>清醒：不是昏沉    如实：不把想象当事实</span></span>
<span class="line"><span>正直：不替欲望寻找借口    不随：觉察以后不继续扩张</span></span></code></pre></div><p><strong>「内观正觉」是整个坐忘实操的起点。</strong></p><h3 id="三、「觉一念起-即须除灭」" tabindex="-1">三、「觉一念起，即须除灭」 <a class="header-anchor" href="#三、「觉一念起-即须除灭」" aria-label="Permalink to &quot;三、「觉一念起，即须除灭」&quot;">​</a></h3><p>重点是「<strong>觉</strong>」在「<strong>除</strong>」前：先觉察，后不随——不是没有看清念头便强行压制。如果连念头是什么都没辨清，只是一味紧张控制，容易形成后文警告的「束心太急」。</p><p>「除灭」的对象是念头的<strong>续接和支配力</strong>，不是强迫大脑永远没有任何活动：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个怨念生起 → 已经看见 → 不继续编造对方的恶 → 不计划报复 → 念头因失去支持而消退</span></span>
<span class="line"><span></span></span>
<span class="line"><span>而错误做法是：怨念生起 → 认为自己不该有念 → 强烈责备自己</span></span>
<span class="line"><span>→ 紧张地要求念头立刻消失 → 反而更加执著这个念头</span></span></code></pre></div><p>后者表面在除念，实际上又增加一层对念头的憎恶。「随起随制，务令安静」的「制」不一定是强制——结合后文「制而无著，放而不逸」，它更接近：看见、截止、不续、返回当下、不让念头自行扩大。</p><h3 id="四、「浮游乱想」也要逐渐止息" tabindex="-1">四、「浮游乱想」也要逐渐止息 <a class="header-anchor" href="#四、「浮游乱想」也要逐渐止息" aria-label="Permalink to &quot;四、「浮游乱想」也要逐渐止息&quot;">​</a></h3><p>「虽非的有贪著」——有些念头并没有明确而强烈的贪欲对象（无目的回忆、随意设想、心中虚构对话、不断预演尚未发生的事）。这些念头看似无害，却使心不能稳定。</p><table tabindex="0"><thead><tr><th>明确贪著</th><th>浮游乱想</th></tr></thead><tbody><tr><td>有具体对象</td><td>未必有具体目标</td></tr><tr><td>欲望较强、推动行为</td><td>内容散乱、消耗注意力</td></tr><tr><td>容易辨认</td><td>容易被忽略</td></tr></tbody></table><p><strong>坐忘不仅要处理粗重欲望，也要处理细微散乱。</strong>「亦尽灭除」仍然是停止接续，不是用强力制造意识空白。</p><p>「昼夜勤行，须臾不替」——不意味着昼夜不眠或全天紧张监控自己，而是强调修习具有连续性：坐时觉察、行时觉察、言语时觉察、处理事务时觉察、爱恶初起时觉察。<strong>若把「须臾不替」理解为持续高压控制，便会违反后文「宽急得中」。</strong></p><h3 id="五、「唯灭动心-不灭照心」" tabindex="-1">五、「唯灭动心，不灭照心」 <a class="header-anchor" href="#五、「唯灭动心-不灭照心」" aria-label="Permalink to &quot;五、「唯灭动心，不灭照心」&quot;">​</a></h3><ul><li><strong>动心</strong>：随境妄动、攀缘造作的心（见利而逐、见毁而怒、见色而染、见异象而惊喜、因智慧而求名），<strong>不是一切正常心理功能</strong>。</li><li><strong>照心</strong>：清醒觉察之心（知道念头生起、知道自己正在被爱恶牵动、能辨别是否必要），与【泰定】的「天光」「几微入照」相应。</li></ul><p>如果只追求一切心理活动消失，容易落入昏沉、麻木、空白、对现实失去判断。真正的坐忘是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>妄动逐渐止息，觉照反而更加清楚</span></span>
<span class="line"><span>（不是：念头减少，觉察也一并熄灭）</span></span></code></pre></div><p><strong>所以判断静境真伪的关键，不是「有没有念头」，而是：静中是否清醒，清醒中是否不随。</strong></p><h3 id="六、「但冥虚心-不冥有心」" tabindex="-1">六、「但冥虚心，不冥有心」 <a class="header-anchor" href="#六、「但冥虚心-不冥有心」" aria-label="Permalink to &quot;六、「但冥虚心，不冥有心」&quot;">​</a></h3><p>这句文字较为古奥，且可能涉及版本、训读问题，应结合前后文谨慎理解。它与前一句形成平行：使虚妄、浮动之心沉寂，不使本有的觉照心陷入昏暗。</p><p>其中「冥」可理解为使之幽寂、隐没；「虚心」在此未必是《道德经》中褒义的虚静心，也可能指浮虚不实的妄心。若按这一解释，整句就是：<strong>只应使虚浮妄心沉寂，不应使具有觉照作用的心也陷入昏冥。</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>所寂灭者：虚妄攀缘</span></span>
<span class="line"><span>所保留者：本有觉照</span></span></code></pre></div><p>不宜仅据字面把它解释成追求意识断灭。</p><h3 id="七、「不依一物-而心常住」" tabindex="-1">七、「不依一物，而心常住」 <a class="header-anchor" href="#七、「不依一物-而心常住」" aria-label="Permalink to &quot;七、「不依一物，而心常住」&quot;">​</a></h3><p>「不依一物」——不把任何境界当作必须攀附的固定支点（外在声色、呼吸感受、身体某处、空白状态、清静体验、神异景象、「我正在入定」的意识），与【收心】「住无所有」一致。</p><p>「而心常住」——虽然不依附任何对象，心却保持清醒、稳定，不随境散失。这防止把「不依」误解成散漫：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不依 ≠ 注意力随意漂流；常住 ≠ 抓住一个固定对象不放</span></span></code></pre></div><p>其理想状态是：<strong>无所依著而不散，无所抓取而常明。</strong></p><h3 id="八、为什么此法「玄妙利益甚深」却难以信受" tabindex="-1">八、为什么此法「玄妙利益甚深」却难以信受 <a class="header-anchor" href="#八、为什么此法「玄妙利益甚深」却难以信受" aria-label="Permalink to &quot;八、为什么此法「玄妙利益甚深」却难以信受&quot;">​</a></h3><p>坐忘的玄妙之处在于，它不通过不断增加能力而成就，反而通过减损：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不增加对象而减少攀缘；不追求异象而恢复觉照</span></span>
<span class="line"><span>不强行制造智慧而由定自然发慧；不从外面取得道而使本心与道相应</span></span></code></pre></div><p>这种「以无所得而得」的结构，容易与普通功利思维冲突。</p><p>「信心无二」——不意味着不能辨伪或不能提问（下一句恰恰说「仍须辨识真伪」），而是<strong>方向坚定 + 方法审慎</strong>。</p><h3 id="九、「虽知诵读其文-仍须辨识真伪」" tabindex="-1">九、「虽知诵读其文，仍须辨识真伪」 <a class="header-anchor" href="#九、「虽知诵读其文-仍须辨识真伪」" aria-label="Permalink to &quot;九、「虽知诵读其文，仍须辨识真伪」&quot;">​</a></h3><p>能够背诵「灭动不灭照」「住无所有」「无心于定」「慧而不用」，不等于现实中已经做到。<strong>经典语言甚至可能被欲望利用：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>因散漫而不收心，却说「不依一物」</span></span>
<span class="line"><span>因逃避责任，却说「无为」</span></span>
<span class="line"><span>因主动多事，却说「处动常寂」</span></span>
<span class="line"><span>因昏沉无知，却说「心若死灰」</span></span></code></pre></div><p>依全文，可以作以下辨别：</p><table tabindex="0"><thead><tr><th>真修</th><th>相似偏差</th></tr></thead><tbody><tr><td>心静而照明</td><td>昏沉麻木</td></tr><tr><td>制而无著</td><td>紧张压抑</td></tr><tr><td>放而不逸</td><td>散漫放纵</td></tr><tr><td>无事安定</td><td>害怕一切事务</td></tr><tr><td>有事能应</td><td>主动增加事务</td></tr><tr><td>慧生而含藏</td><td>得少慧便多辩</td></tr><tr><td>见异象不取</td><td>以异象证明成就</td></tr></tbody></table><h3 id="十、妨碍悟道的四重障碍" tabindex="-1">十、妨碍悟道的四重障碍 <a class="header-anchor" href="#十、妨碍悟道的四重障碍" aria-label="Permalink to &quot;十、妨碍悟道的四重障碍&quot;">​</a></h3><p>「<strong>声色昏心</strong>」——感官刺激长期占据注意，心便难以保持清明（持续信息刺激、强烈娱乐、以感官兴奋逃避内心）。感官本身不是罪过，成问题的是长期沉溺。</p><p>「<strong>邪佞惑耳</strong>」——修行者若只喜欢听对自己的赞美、神奇而夸张的承诺、快速成就之法、迎合欲望的解释，就容易偏离坐忘的减损之道。</p><p>「<strong>人我成性</strong>」——总要比较高下、总要证明己见、把他人评价当作自我价值、把修行也变成胜负竞争。<strong>只要「我比别人更有境界」的心仍然强烈，便很难真正忘名。</strong></p><p>「<strong>自是病深</strong>」——坚信只有自己正确、不肯反观盲点，是极深的心病。它会使人：把妄想看作真观、把紧张看作精进、把异象看作得道、把好辩看作弘法。<strong>因此「辨识真伪」首先要能怀疑自己的解释。</strong></p><p>「心与道隔」不是大道有意远离人，而是这些形成遮蔽：<strong>道并未失，但心被妄执占据；不是道不来，而是心中无处容道。</strong></p><h3 id="十一、三戒-简缘、无欲、静心" tabindex="-1">十一、三戒：简缘、无欲、静心 <a class="header-anchor" href="#十一、三戒-简缘、无欲、静心" aria-label="Permalink to &quot;十一、三戒：简缘、无欲、静心&quot;">​</a></h3><p>「戒」在这里不只是一组禁止性规范，更是保护心神的三种根本原则。</p><table tabindex="0"><thead><tr><th>戒</th><th>内涵</th><th>总摄</th></tr></thead><tbody><tr><td><strong>简缘</strong></td><td>精简使心攀附、耗散的因缘（不以功利机心结交、不主动扩大无必要关系、不把毁誉带入心中）</td><td>【断缘】【简事】</td></tr><tr><td><strong>无欲</strong></td><td>不以占有为安、不把喜好当作必需、不追求声色名利与修道异能</td><td>【真观】对衣食色欲贫病生死万境爱恶的观察</td></tr><tr><td><strong>静心</strong></td><td>动念能觉、觉而不随、灭动不灭照、不依一物而心常住</td><td>【收心】【泰定】</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>缘不简 → 外境不断扰心；欲不减 → 即使独处仍会内求；心不静 → 简缘无欲也可能只是强行压制</span></span>
<span class="line"><span>简缘 → 减少外在诱因；无欲 → 松开内在黏著；静心 → 使心归于清明安定</span></span></code></pre></div><p><strong>三者必须相互支持。</strong></p><p>「<strong>在终如始</strong>」——修习常见的问题是：开始时谨慎，稍有静境后便放松；开始时简缘，得少慧后又广结人事；开始时无欲，后来贪著修行名声。<strong>所以越接近后段，越要防止因定慧所得而重新生欲。</strong></p><h3 id="十二、「无心求道-而道自来」" tabindex="-1">十二、「无心求道，而道自来」 <a class="header-anchor" href="#十二、「无心求道-而道自来」" aria-label="Permalink to &quot;十二、「无心求道，而道自来」&quot;">​</a></h3><p>这不是说完全不必求道——前文已要求深生信慕、受持三戒、昼夜勤行、在终如始。这里的「无心求道」是说，实行三戒以后，<strong>不要再以贪得之心催逼结果</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>可以勤行，不可贪果；可以调心，不可逼慧；可以持戒，不可计算何时得道</span></span></code></pre></div><p>「人能虚心无为，非欲于道，道自归之」——这是《坐忘论》反复强调的逆向逻辑：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>心越想抓住道 → 越是有欲有为</span></span>
<span class="line"><span>心虚而不求所得 → 与道的虚无自然相应</span></span></code></pre></div><p>「简要之法，实可信哉，实可贵哉」——三戒看似简单，却切中根本：<strong>方法少，并不等于功夫浅；正因为直接处理心之根本，所以「力少功多」。</strong></p><h3 id="十三、凡心为什么如此难调" tabindex="-1">十三、凡心为什么如此难调 <a class="header-anchor" href="#十三、凡心为什么如此难调" aria-label="Permalink to &quot;十三、凡心为什么如此难调&quot;">​</a></h3><p>「凡心躁竞，其来固久」——凡俗心的躁动、争竞并非一日形成，而是长期习惯的结果。所以一开始安静时，反而会感到不适。</p><p>「息之而不得」——想使心安静却完全做不到，这是<strong>正常的初步阶段</strong>，不表示此法无效，而说明过去散乱习惯力量很强。</p><p>「暂得而还失」——有时稍得安静，过一会儿又重新散乱。这同样是调心必经过程：<strong>初步安静不是永久成就，重新散乱也不是全部失败。</strong> 重要的是再觉、再收。</p><p>「<strong>去留交战</strong>」——一部分心想离开妄念，另一部分又想继续追随：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>知道不应继续愤怒，却仍想证明自己受了委屈</span></span>
<span class="line"><span>知道事务应当停止，却仍舍不得其中名利</span></span></code></pre></div><p>「百体流汗」是对收心困难的强烈身体描写：用力控制时全身紧张甚至汗出。<strong>它不应被当作修习成功的标志，反而提示用力可能过猛</strong>——后文立即警告「束心太急，急则成病」。</p><p>「久久柔挺，方乃调熟」的关键仍在「久久」，不是一时猛烈。</p><h3 id="十四、「莫以暂收不得-遂废平生之业」" tabindex="-1">十四、「莫以暂收不得，遂废平生之业」 <a class="header-anchor" href="#十四、「莫以暂收不得-遂废平生之业」" aria-label="Permalink to &quot;十四、「莫以暂收不得，遂废平生之业」&quot;">​</a></h3><p>这句话同时反对两种极端：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>急于求成：几次静坐无效便失望</span></span>
<span class="line"><span>自我否定：念头很多便认为自己无缘</span></span></code></pre></div><p><strong>真正的衡量单位不是一次坐得是否安静，而是长期趋势：</strong> 是否更快觉察？是否更少续接？是否更能从情绪中恢复？是否更少主动制造事务？是否逐渐不受毁誉牵引？</p><h3 id="十五、少得静后-如何进入行住坐卧" tabindex="-1">十五、少得静后，如何进入行住坐卧 <a class="header-anchor" href="#十五、少得静后-如何进入行住坐卧" aria-label="Permalink to &quot;十五、少得静后，如何进入行住坐卧&quot;">​</a></h3><p>次序不能颠倒：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先在无事处练习安心，再将安心带入必要事务</span></span>
<span class="line"><span>（不是一开始主动投身繁杂，然后声称以事炼心）</span></span></code></pre></div><p>「行立坐卧」——行走时不随想、站立时觉察身体、坐时清醒不昏、卧时不继续浮想。「涉事喧阓」——修习逐渐成熟后，即使处理必要事务、身处喧闹，也要有意保护心的安定（这里仍是「作意安之」，尚未达到【泰定】的「无心于定」）。</p><p>「有事无事，常若无心」——不是不负责任，而是事情来时适当处理、不加入额外爱恶、事情结束以后不再留滞。「处静处喧，其志唯一」——不论外境怎样变化，都以不逐、不贪、不乱为根本志向。</p><h3 id="十六、「束心太急-急则成病」——全篇最重要的安全警告" tabindex="-1">十六、「束心太急，急则成病」——全篇最重要的安全警告 <a class="header-anchor" href="#十六、「束心太急-急则成病」——全篇最重要的安全警告" aria-label="Permalink to &quot;十六、「束心太急，急则成病」——全篇最重要的安全警告&quot;">​</a></h3><p><strong>什么是束心太急？</strong> 强迫自己完全无念、一念出现便严厉自责、长时间屏息紧绷身体、为追求定境而严重减少睡眠、将正常感知视为修行失败、试图用意志压住全部情绪。<strong>这种方式使修习由安定转成持续对抗。</strong></p><p>「气发狂痴，是其候也」——用现代语言看，值得警惕的情况包括：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>长期失眠 · 极端兴奋或焦躁 · 恐慌、解离 · 明显幻听幻视</span></span>
<span class="line"><span>认知混乱 · 行为失控 · 坚信自己获得特殊使命 · 日常功能明显下降</span></span></code></pre></div><p><strong>若出现这些状态，不应解释为「即将得道」或继续加大修习强度。</strong> 应当：</p><ol><li>立即停止强制性、长时间的练习；</li><li>恢复睡眠、饮食与日常活动；</li><li>告知可信任的亲友；</li><li>必要时及时寻求精神科、心理或其他医疗专业帮助。</li></ol><p><strong>原文自身已经明确把「狂痴」列为病候，而非成就。</strong></p><h3 id="十七、心不动以后为什么还要「放任」" tabindex="-1">十七、心不动以后为什么还要「放任」 <a class="header-anchor" href="#十七、心不动以后为什么还要「放任」" aria-label="Permalink to &quot;十七、心不动以后为什么还要「放任」&quot;">​</a></h3><p>当心已经稍微安定时，如果仍不断加强控制，容易形成紧绷、僵硬、对安静的执著、害怕念头出现。所以心安以后，要适度放松。</p><p>「放任」不是放纵——它是<strong>解除多余控制，让心自然安住</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>强制：时时盯住心，怕它移动</span></span>
<span class="line"><span>放纵：任由心追逐爱恶</span></span>
<span class="line"><span>放任：心已安定，不再多加干预</span></span></code></pre></div><p>「宽急得中」——调心既不能过于宽松，也不能过于急迫：</p><table tabindex="0"><thead><tr><th>太急</th><th>太宽</th></tr></thead><tbody><tr><td>紧张压制</td><td>随念漂流</td></tr><tr><td>害怕起念</td><td>不知心已散乱</td></tr><tr><td>容易身心失衡</td><td>无法形成定力</td></tr></tbody></table><p>「常自调适」——根据当下状态调节：昏沉时稍提起觉照、散乱时稍加收摄、紧张时放松身体与控制、清醒安定时不再多作。「得中」不是一个永远固定的力度，而要根据当下状态调节。</p><h3 id="十八、「制而无著-放而不逸」" tabindex="-1">十八、「制而无著，放而不逸」 <a class="header-anchor" href="#十八、「制而无著-放而不逸」" aria-label="Permalink to &quot;十八、「制而无著，放而不逸」&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>制：保证不散    无著：保证不僵</span></span>
<span class="line"><span>放：保证不紧    不逸：保证不乱</span></span></code></pre></div><ul><li><strong>制而无著</strong>：需要收摄时便收摄，但不执著于控制，也不执著于一个固定的静境——制止念头继续，却不仇恨念头；返回安静，却不把安静据为己有。</li><li><strong>放而不逸</strong>：需要放松时便放松，但不因此陷入散漫和欲望——身体放松，觉照不失，心不紧绷，也不随境漂流。</li></ul><p><strong>这就是「宽急得中」。</strong></p><h3 id="十九、「处喧无恶-涉事无恼者-此真定也」" tabindex="-1">十九、「处喧无恶，涉事无恼者，此真定也」 <a class="header-anchor" href="#十九、「处喧无恶-涉事无恼者-此真定也」" aria-label="Permalink to &quot;十九、「处喧无恶，涉事无恼者，此真定也」&quot;">​</a></h3><p>「处喧无恶」——身处喧闹环境，不因喧闹而立刻生起嫌恶。<strong>如果静心完全依赖寂静环境，一有声音便愤怒，说明所守的仍是环境，不是心。</strong>（但「无恶」不表示必须忍受有害噪声，可以合理离开或保护听力。）</p><p>「涉事无恼」——处理必要事务时，心不因事情本身生起烦躁和纠缠。真定不是完全不能做事，而是事来能应、应时不乱、事后不留。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>只有无事时静 → 定仍依赖外境</span></span>
<span class="line"><span>处喧涉事而不乱 → 心开始具有自主性</span></span></code></pre></div><h3 id="二十、能处喧涉事-不等于应主动求喧求事" tabindex="-1">二十、能处喧涉事，不等于应主动求喧求事 <a class="header-anchor" href="#二十、能处喧涉事-不等于应主动求喧求事" aria-label="Permalink to &quot;二十、能处喧涉事，不等于应主动求喧求事&quot;">​</a></h3><p>「不以涉事无恼，故求多事；不以处喧无动，故来就喧」——即便已经能够应事不烦，也不能因此说「我可以在事上炼心，所以应当承担更多事务」。这往往隐藏着表现能力、求取影响、证明定力、借弘道之名扩大人事。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>能面对诱惑 ≠ 应主动靠近诱惑</span></span>
<span class="line"><span>能在冲突中保持冷静 ≠ 应主动制造冲突</span></span></code></pre></div><p><strong>真正的定没有证明自己的需要。</strong></p><h3 id="二十一、「以无事为真定-以有事为应迹」与水镜之喻" tabindex="-1">二十一、「以无事为真定，以有事为应迹」与水镜之喻 <a class="header-anchor" href="#二十一、「以无事为真定-以有事为应迹」与水镜之喻" aria-label="Permalink to &quot;二十一、「以无事为真定，以有事为应迹」与水镜之喻&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>无事清静 → 体；有事而应 → 用；应事结束 → 复归无事</span></span></code></pre></div><p>「无事」不仅是外面暂时没有任务，也包括内心不主动制造事务（不翻旧账、不预演争论、不虚构问题）。<strong>不能把「用」变成新的常态，使心永远处于主动经营之中。</strong></p><p>「若水镜之为鉴，则遇物而见形」——清水和明镜本身不主动寻找形象，但对象来到面前便自然映现：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>物未至 → 镜不预先造像；物既至 → 如实映现；物离去 → 镜不保存其影</span></span></code></pre></div><table tabindex="0"><thead><tr><th>无为应事</th><th>主动多事</th></tr></thead><tbody><tr><td>事来则应</td><td>无事生事</td></tr><tr><td>依必要而行</td><td>因自我表现而行</td></tr><tr><td>应后即止</td><td>触类而长</td></tr></tbody></table><p>镜心仍能辨明善恶、利害与责任，只是不被爱恶扭曲——<strong>伤害需要制止，责任需要承担，但应物之后不把功过名相长期留在心中。</strong></p><h3 id="二十二、人能善巧入定-不能强迫慧生" tabindex="-1">二十二、人能善巧入定，不能强迫慧生 <a class="header-anchor" href="#二十二、人能善巧入定-不能强迫慧生" aria-label="Permalink to &quot;二十二、人能善巧入定，不能强迫慧生&quot;">​</a></h3><p>人能够安排合适环境、端正坐姿、简缘减欲、调节松紧、规律练习——这些都是入定的方便。但<strong>人为努力所能做的，是创造虚静清明的条件，而不是直接制造本慧</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>人能清除遮蔽，不能把慧当作物品生产</span></span>
<span class="line"><span>人能保持安定，不能命令悟境立即出现</span></span></code></pre></div><p>「发慧迟速，则不由人」——因为智慧是「慧出本性，非适今有」，它依赖于旧习厚薄、定力深浅、信行是否持久、是否执著求慧。</p><h3 id="二十三、「勿于定中急急求慧」与「慧而不用」" tabindex="-1">二十三、「勿于定中急急求慧」与「慧而不用」 <a class="header-anchor" href="#二十三、「勿于定中急急求慧」与「慧而不用」" aria-label="Permalink to &quot;二十三、「勿于定中急急求慧」与「慧而不用」&quot;">​</a></h3><p>「我要赶快发慧」本身就是一个强烈妄念：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>已经稍静 → 开始检查是否发慧 → 没有特殊体验 → 生起焦虑</span></span>
<span class="line"><span>→ 越焦虑越频繁检查 → 心越不静</span></span></code></pre></div><p><strong>故「求慧则伤定，伤定则无慧」。</strong> 急求慧还会使人把普通现象（突然出现的念头、视觉光点、梦境、身体震动、强烈情绪、对某事的直觉确信）误认为智慧——<strong>求慧越急，越容易选择性解释经验，并形成自我暗示。</strong></p><p>「定不求慧，而慧自生」就是【泰定】的「宇泰定者，发乎天光」。<strong>真慧的标准不是体验奇特，而是它来自稳定清明</strong>，并能照见爱恶、减少妄动、使心更加恬静、不强化自我名相。<strong>如果所谓智慧令人更自负、更躁动、更爱争辩，就很可能不是真慧。</strong></p><p>「实智若愚」不是故意装傻，而是不抢先表现、不事事发表见解、不用辩论证明高明。「益资定慧，双美无极」：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定生慧 → 慧照见多知多事之害 → 不向外驰 → 定更加稳固 → 慧更加清净</span></span></code></pre></div><h3 id="二十四、定中出现「多感、百魅」怎么办" tabindex="-1">二十四、定中出现「多感、百魅」怎么办 <a class="header-anchor" href="#二十四、定中出现「多感、百魅」怎么办" aria-label="Permalink to &quot;二十四、定中出现「多感、百魅」怎么办&quot;">​</a></h3><p>「若定中念想，则有多感，众邪百魅，随心应现」——入静以后如果仍有细微想念活动，便可能出现各种感应和景象，因为外在刺激减少，内在的记忆、想象、恐惧、宗教期待、身体感觉可能变得格外鲜明。<strong>关键在「随心」二字：景象依心念而现，不应立即认定为外在真实存在。</strong></p><p>「真人老君，神异诡怪，是其祥也」——<strong>即使显现的不是恐怖鬼魅，而是真人、老君、神仙、光明、庄严形象，也仍可能是定中想念与宗教记忆所呈现。不能因为形象神圣，便自动判定为真实证验。</strong></p><p>「祥」在古汉语中既可指吉祥征兆，也可指征候、异象；结合上下文，此处更适合谨慎理解为「定中念想产生感应时可能出现的异象或征候」。<strong>它们不是本文要求追逐的目标</strong>——下一句立即把真正方向规定为「定心之上，豁然无覆；定心之下，旷然无基」，也就是应越过一切具体形象，不取鬼魅，也不取真人老君之相。</p><p><strong>实际处理原则</strong>：不追逐、不对话、不解释为使命、不因神圣形象而自认得道、回到平稳呼吸与身体感受、必要时停止练习并充分休息。<strong>若在非静坐状态下也持续出现幻听幻视、妄想确信、失眠兴奋或功能受损，应及时寻求专业医疗帮助，而不应以「真人显现」解释。</strong></p><h3 id="二十五、「定心之上-豁然无覆-定心之下-旷然无基」" tabindex="-1">二十五、「定心之上，豁然无覆；定心之下，旷然无基」 <a class="header-anchor" href="#二十五、「定心之上-豁然无覆-定心之下-旷然无基」" aria-label="Permalink to &quot;二十五、「定心之上，豁然无覆；定心之下，旷然无基」&quot;">​</a></h3><p>「豁然无覆」——真正的定心上方开阔明朗，没有任何观念、形象和执著覆盖（不是鬼神覆盖心、光明覆盖心、某种概念覆盖心、「我已得定」的意识覆盖心）。</p><p>「旷然无基」——定心下方广大无依，没有固定对象作为支撑（不依声色、不依空境、不依异象、不依身体某处、不依自我身份），与「不依一物，而心常住」一致。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上无覆盖 → 不受名相、异象和成见遮蔽</span></span>
<span class="line"><span>下无所依 → 不抓住任何境界作为自性</span></span>
<span class="line"><span>虽然无覆无基 → 觉照仍然明朗</span></span></code></pre></div><p><strong>这不是坠入虚无，而是无所著的清明。</strong></p><h3 id="二十六、「旧业永消-新业不造」" tabindex="-1">二十六、「旧业永消，新业不造」 <a class="header-anchor" href="#二十六、「旧业永消-新业不造」" aria-label="Permalink to &quot;二十六、「旧业永消，新业不造」&quot;">​</a></h3><p>在原典宗教语境中，旧业指过去身口意行为形成的业力；通过不再随念、不再以爱恶强化旧习、不再重复相同行为，旧有业习逐渐失去延续条件。不造新业并非完全不行动，而是不以贪、嗔、痴和自我占有推动行动（事情来则如实回应，回应以后不居功、不留怨）。</p><p>「无所缠碍，迥脱尘网」——「尘网」不是社会本身，而是名利网、毁誉网、欲望网、人我网、自是网。「行而久之，自然得道」——得道仍然依赖「久之」：一时无念不等于得道，一次异象不等于得道，<strong>长期三戒不退、定慧相养，才是自然得道的路线</strong>。</p><h3 id="二十七、心有五时" tabindex="-1">二十七、心有五时 <a class="header-anchor" href="#二十七、心有五时" aria-label="Permalink to &quot;二十七、心有五时&quot;">​</a></h3><p>「时」不是固定时长，而是修心进展的五个阶段。</p><table tabindex="0"><thead><tr><th>时</th><th>状态</th><th>要点</th></tr></thead><tbody><tr><td>一 · 动多静少</td><td>心多数时间随境而动，偶尔能静，念起很久才发现</td><td>大多数初学者状态：不求完全无念，先增加觉察次数；不因散乱自责</td></tr><tr><td>二 · 动静相半</td><td>心动与心静大致相当，有时能及时发现念头</td><td>风险：因已有进步而认为自己已得定、主动接触更多事务</td></tr><tr><td>三 · 静多动少</td><td>心多数时间相对安静，念起后较快恢复</td><td>仍可能在强烈境界前失守、对安静产生执著</td></tr><tr><td>四 · 无事则静，事触还动</td><td>无事务时可以稳定安静；遇毁誉、得失、突发、病痛仍明显动摇</td><td><strong>关键的辨别阶段</strong>：静室中长时间无念，并不必然胜过能在现实中妥善应事的人</td></tr><tr><td>五 · 心与道合，触而不动</td><td>外境接触时不再因贪爱怨恶失去根本安定</td><td>感知发生而不染著、判断发生而不由私欲扭曲、情绪可能出现而不成为心的主人</td></tr></tbody></table><p><strong>五时并非简单直线上升</strong>：平常处于「静多动少」，遇重大变故又变成「动多静少」；某一类境界触而不动，另一类仍会强烈摇动。因此五时更像<strong>观察坐标</strong>，而不是一次通过便永久升级的阶梯——可以分别观察对名、对利、对亲疏、对疾病、对批评、对修行成就的反应。</p><p>「心至此地，始得安乐」——前四时的静仍部分依赖条件（无事才静、无人批评才静、身体舒适才静），条件一变安定也会失去；第五时则是境界可以变化而心不再随之彻底翻转。<strong>这里描述的是极高境界，不宜因短暂平静便自称已经「罪垢灭尽」。</strong></p><h3 id="二十八、身有七候" tabindex="-1">二十八、身有七候 <a class="header-anchor" href="#二十八、身有七候" aria-label="Permalink to &quot;二十八、身有七候&quot;">​</a></h3><table tabindex="0"><thead><tr><th>候</th><th>原文</th><th>要点</th></tr></thead><tbody><tr><td>一</td><td>举动顺时，容色和悦</td><td>行动合乎时机、不躁进不迟滞；面容和顺气色悦泽——最基础的形神协调（但气色也受睡眠、疾病、营养影响）</td></tr><tr><td>二</td><td>夙疾普消，身心轻爽</td><td>长期疾病逐渐消退，身心轻安。<strong>现实中不能承诺所有慢性病必然痊愈</strong>；患病仍应接受合理医疗</td></tr><tr><td>三</td><td>填补夭伤，还元复命</td><td>补复生命过去的损伤，恢复生命元气。属道教炼养理论</td></tr><tr><td>四</td><td>延数千岁，名曰仙人</td><td>明确的道教神仙信仰陈述，不能按现代人类寿命资料视为已证实事实</td></tr><tr><td>五</td><td>链形为气，名曰真人</td><td>「链」通「炼」：将粗重形质炼化为精微之气</td></tr><tr><td>六</td><td>炼气成神，名曰神人</td><td>使精微之气转化为虚灵之神</td></tr><tr><td>七</td><td>炼神合道，名曰至人</td><td>使神与大道冥合——七候最高层次，不再有一个独立自我占有道</td></tr></tbody></table><p><strong>仙人、真人、神人、至人的层次</strong>（依本篇七候内部结构）：</p><table tabindex="0"><thead><tr><th>层次</th><th>主要转化</th><th>核心特征</th></tr></thead><tbody><tr><td>仙人</td><td>寿命延长</td><td>超越普通寿限</td></tr><tr><td>真人</td><td>炼形为气</td><td>粗质转为精微</td></tr><tr><td>神人</td><td>炼气成神</td><td>气进一步神化</td></tr><tr><td>至人</td><td>炼神合道</td><td>神与大道冥一</td></tr></tbody></table><p>（《庄子》及不同道教经典对这些名号的排列和含义并不完全一致，本表只表示本篇这一段内部的层次结构。）</p><p>「<strong>鉴力随候益明</strong>」——随着心身转化层次加深，观照能力也越来越清明（心渐安定→爱恶减少；形神协调→觉照不受扰乱）。「得至道成，慧乃圆备」反过来限制一切过早的自我认定：得少慧不等于慧已圆满。</p><h3 id="二十九、「虽久学定心-身无五时七候者」" tabindex="-1">二十九、「虽久学定心，身无五时七候者」 <a class="header-anchor" href="#二十九、「虽久学定心-身无五时七候者」" aria-label="Permalink to &quot;二十九、「虽久学定心，身无五时七候者」&quot;">​</a></h3><p>这句底文存在值得注意的问题：前文是「心有五时，身有七候」，此处却说「身无五时七候」。按义理，更合理的理解可能是「心未具五时、身未具七候」，也可能是统称身心未现相应层次。<strong>无论如何，它是在批评只有自称慧觉而无身心实际证验的情况。</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>念少 ≠ 真定；见光 ≠ 天光；有感 ≠ 得道；能辩 ≠ 有慧；心有所悟 ≠ 形神俱成</span></span></code></pre></div><p><strong>但从现代视角，寿命和身体状况受遗传、疾病、环境、医疗等复杂因素影响，绝不能以早逝或患病断定一个人「道德低劣」或「修行虚假」。</strong> 这里表达的是本篇内部的宗教证成标准。</p><h3 id="三十、三戒、五时、七候总表" tabindex="-1">三十、三戒、五时、七候总表 <a class="header-anchor" href="#三十、三戒、五时、七候总表" aria-label="Permalink to &quot;三十、三戒、五时、七候总表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>系统</th><th style="text-align:right;">层次</th><th>原文</th><th>主要意义</th></tr></thead><tbody><tr><td>三戒</td><td style="text-align:right;">一</td><td>简缘</td><td>减少外在人事和功利攀缘</td></tr><tr><td>三戒</td><td style="text-align:right;">二</td><td>无欲</td><td>松开对声色、名利和境界的占有</td></tr><tr><td>三戒</td><td style="text-align:right;">三</td><td>静心</td><td>灭妄动而保存觉照</td></tr><tr><td>五时</td><td style="text-align:right;">一</td><td>动多静少</td><td>散乱为主，偶得安静</td></tr><tr><td>五时</td><td style="text-align:right;">二</td><td>动静相半</td><td>安静与妄动大致相当</td></tr><tr><td>五时</td><td style="text-align:right;">三</td><td>静多动少</td><td>安定渐多，散乱渐少</td></tr><tr><td>五时</td><td style="text-align:right;">四</td><td>无事则静，事触还动</td><td>静处能定，触境仍乱</td></tr><tr><td>五时</td><td style="text-align:right;">五</td><td>心与道合，触而不动</td><td>应物而不染，动静不失其定</td></tr><tr><td>七候</td><td style="text-align:right;">一</td><td>举动顺时，容色和悦</td><td>行为合宜，形色和畅</td></tr><tr><td>七候</td><td style="text-align:right;">二</td><td>夙疾普消，身心轻爽</td><td>形神负担减轻</td></tr><tr><td>七候</td><td style="text-align:right;">三</td><td>填补夭伤，还元复命</td><td>修补损耗，恢复本元</td></tr><tr><td>七候</td><td style="text-align:right;">四</td><td>延数千岁，名曰仙人</td><td>原典所说的超常长生</td></tr><tr><td>七候</td><td style="text-align:right;">五</td><td>炼形为气，名曰真人</td><td>粗重之形转为精微之气</td></tr><tr><td>七候</td><td style="text-align:right;">六</td><td>炼气成神，名曰神人</td><td>精气进一步转化为神</td></tr><tr><td>七候</td><td style="text-align:right;">七</td><td>炼神合道，名曰至人</td><td>神与大道冥合</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三戒：回答「从哪里下手」</span></span>
<span class="line"><span>五时：回答「心静到了哪一步」</span></span>
<span class="line"><span>七候：回答「形神转化到了哪一步」</span></span></code></pre></div><p><strong>五时检验「心是否真正安定」</strong>（最关键的分界在第四时与第五时，说明静坐中的平静不是唯一标准）；<strong>七候检验「道力是否由心及形」</strong>（承接【得道】「深则兼被于形，浅则唯及于心」）。</p><p><strong>但不可用疾病和寿命简单裁判他人</strong>：疾病受遗传、感染、环境等多种因素影响；患病不等于修行失败；早逝不等于道德有亏；长寿也不能自动证明已经得道。<strong>这些「候」适合用于理解原典的形神俱化理想，不应成为评判现实患者或修行者的工具。</strong></p><h3 id="《枢翼》对修行次第的四重校正" tabindex="-1">《枢翼》对修行次第的四重校正 <a class="header-anchor" href="#《枢翼》对修行次第的四重校正" aria-label="Permalink to &quot;《枢翼》对修行次第的四重校正&quot;">​</a></h3><p><strong>第一重：不是一味压念，而是「灭动不灭照」</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误路线：追求无念 → 强力压制 → 觉知昏暗 → 把麻木误认为定</span></span>
<span class="line"><span>正确路线：念起能觉 → 觉而不续 → 妄动止息 → 觉照更加清明</span></span></code></pre></div><p><strong>第二重：不是越用力越好，而是「宽急得中」</strong>——过急则紧张执著身心失衡，过宽则漂流散漫随欲放逸；正确方法是「制而无著，放而不逸」。</p><p><strong>第三重：不是故意入世试定，而是「无事为体，有事为用」</strong>——能处喧不动是定力成熟的表现，但若为了证明境界而主动趋喧求事，仍然是求名和造作。正确结构是：无事时自然安定不主动生事；有事时随缘应对不烦不乱；事情结束不留其影，复归无事。</p><p><strong>第四重：不是急求慧和异象，而是「定极慧生，见异不取」</strong>——急求慧会检查、期待、紧张，反而伤定；执异象会惊喜、解释、自我膨胀，重新形成爱著。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定不求慧 → 慧由本性自生</span></span>
<span class="line"><span>定中现相 → 知其随心而现 → 不取不随</span></span></code></pre></div><h3 id="与《坐忘论》七篇的对应" tabindex="-1">与《坐忘论》七篇的对应 <a class="header-anchor" href="#与《坐忘论》七篇的对应" aria-label="Permalink to &quot;与《坐忘论》七篇的对应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>七篇</th><th>《枢翼》的对应</th></tr></thead><tbody><tr><td>敬信</td><td>「去邪僻之行」：使修道建立在端正行为上，而非追求奇异技术</td></tr><tr><td>断缘、简事</td><td>「外事都绝」压缩为「简缘」：断除功利人事 + 精简非必要事务</td></tr><tr><td>收心</td><td>「随起随制」之外补充松紧原则「制而无著，放而不逸」，防止把收心误解成粗暴压心</td></tr><tr><td>真观</td><td>「无欲」：把观察衣食色欲贫病生死的诸法归纳为一戒</td></tr><tr><td>泰定</td><td>「定不求慧，而慧自生」与「勿于定中急急求慧」：人可创造条件，不能以贪求制造本慧</td></tr><tr><td>得道</td><td>「五时七候」展开「浅则唯及于心，深则兼被于形」，最终归向「炼神合道，名曰至人」</td></tr></tbody></table><h3 id="与《天隐子》的对应" tabindex="-1">与《天隐子》的对应 <a class="header-anchor" href="#与《天隐子》的对应" aria-label="Permalink to &quot;与《天隐子》的对应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>《天隐子》</th><th>本篇</th><th>呼应</th></tr></thead><tbody><tr><td>斋戒四（节食调中，食勿令饱）</td><td>先去邪僻之行，保持基本饮食睡眠</td><td>都从生活秩序入手，不在混乱中强求深定</td></tr><tr><td>安处五（调风气明暗，心目皆安）</td><td>外事都绝，无以干心</td><td>都为修心创造不受干扰的条件</td></tr><tr><td>渐门三（了一则渐次至二；渐而进之）</td><td>三戒 → 五时 → 七候</td><td>都是循序渐进的进程描述</td></tr><tr><td>坐忘七（心不动；因存想而得，因存想而忘）</td><td>制而无著，放而不逸；由作意到自然</td><td>都强调先有意收心，终至不刻意而安</td></tr><tr><td>神解八（信定闲慧四门通神）</td><td>定不求慧，而慧自生；慧而不用</td><td>都不以异象或神通为得道证明</td></tr></tbody></table><h3 id="《坐忘枢翼》最重要的八句话" tabindex="-1">《坐忘枢翼》最重要的八句话 <a class="header-anchor" href="#《坐忘枢翼》最重要的八句话" aria-label="Permalink to &quot;《坐忘枢翼》最重要的八句话&quot;">​</a></h3><blockquote><p><strong>觉一念起，即须除灭，随起随制。</strong><strong>唯灭动心，不灭照心。</strong><strong>不依一物，而心常住。</strong><strong>简缘、无欲、静心。</strong><strong>宽急得中，常自调适。</strong><strong>制而无著，放而不逸。</strong><strong>以无事为真定，以有事为应迹。</strong><strong>定不求慧，而慧自生。</strong></p></blockquote><h3 id="容易误解的地方" tabindex="-1">容易误解的地方 <a class="header-anchor" href="#容易误解的地方" aria-label="Permalink to &quot;容易误解的地方&quot;">​</a></h3><ol><li><strong>「外事都绝」不是抛弃必要责任</strong>——应绝的是非必要、功利性、扰心之事；衣食、医疗和合理责任仍须处理。</li><li><strong>「除灭念头」不是压制一切心理活动</strong>——所灭的是妄念的续接，不是知觉、理性和正常情绪。</li><li><strong>「须臾不替」不是全天高度紧张</strong>——它指修行方向连续，不是持续监控每一个心理活动。</li><li><strong>「不依一物」不是注意力涣散</strong>——心无所著，却保持常住和清明。</li><li><strong>「无心」不是不负责任</strong>——无心是无贪取、无自我炫示；必要事务仍要适当完成。</li><li><strong>「触而不动」不是情感麻木</strong>——它是不被爱恶夺走根本，不是对他人痛苦冷漠。</li><li><strong>「真人老君显现」不等于真实神降</strong>——原文强调这些景象可能「随心应现」，因此不可执取。</li><li><strong>「旧业永消」不是逃避行为责任</strong>——过去造成的现实后果仍需承担、补救；所消的是旧习不再继续获得心行支持。</li><li><strong>「夙疾普消」不能替代医疗</strong>——修习可能改善部分压力相关状态，但不能保证所有疾病痊愈。</li><li><strong>「延数千岁」属于神仙信仰</strong>——不能作为现实养生承诺，也不能据此进行危险修炼。</li><li><strong>「形、气、神、道」是原典修炼结构</strong>——它不能未经论证地等同于现代物理学、神经科学或医学概念。</li><li><strong>五时七候不能用来评判他人</strong>——这些是原典内部的修行图式，不应成为羞辱患者、短寿者或不同信仰者的标准。</li></ol><h3 id="核心实践法" tabindex="-1">核心实践法 <a class="header-anchor" href="#核心实践法" aria-label="Permalink to &quot;核心实践法&quot;">​</a></h3><p><strong>第一步 先整顿行为与生活</strong>——停止明显有害的行为，精简非必要关系和事务，保持基本饮食、睡眠与安全，不在生活极度混乱时强求深定。</p><p><strong>第二步 选择相对安稳的时段端坐</strong>——坐姿以稳定、放松、呼吸自然、不强忍剧痛为原则；不必为了模仿「槁木」而使身体僵硬。</p><p><strong>第三步 念起即觉，但不与念交战</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>念头出现 → 知道它出现 → 不分析、不续写 → 让它自然减弱</span></span>
<span class="line"><span>注意已经散失 → 温和带回 → 再次散失 → 再次带回</span></span></code></pre></div><p>重点是<strong>重复而不自责</strong>。</p><p><strong>第四步 根据状态调节松紧</strong>——心太散略加收摄，心太紧放松控制，心昏沉提起清明觉察，心已安不再多作干预。</p><p><strong>第五步 不检查自己是否发慧</strong>——静坐时不反复追问「有没有悟」「是否进入某层定」「为什么还没有异象」，这些问题会把定重新变成得失竞争。</p><p><strong>第六步 异象出现时不作宗教认定</strong>——无论所见令人恐惧还是庄严神圣，都先视为身心现象：不跟随、不对话、不执行所谓指令、不据此作重大决定、不向外宣称获得使命。<strong>持续影响现实功能时，应停止练习并寻求专业帮助。</strong></p><p><strong>第七步 把安静逐步带入必要事务</strong>——不是主动增加事情，而是在本来必须处理的事务中练习：事来则应、不预先焦虑、事毕即止、不将结果反复带回心中。</p><p><strong>第八步 以长期趋势判断，而非一次体验</strong>——观察：从妄念中恢复是否更快？对毁誉是否稍微淡薄？是否减少无必要争论？身心是否总体更有节度？<strong>这些比一次「无念」或见光、见神更可靠。</strong></p><h3 id="修习中的安全边界" tabindex="-1">修习中的安全边界 <a class="header-anchor" href="#修习中的安全边界" aria-label="Permalink to &quot;修习中的安全边界&quot;">​</a></h3><p>《枢翼》自己已经指出：「若束心太急，急则成病，气发狂痴，是其候也。」<strong>因此，以下情况不应被美化成「破关」或「得道前兆」：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>连续严重失眠 · 长时间不吃不喝 · 持续恐慌或精神恍惚</span></span>
<span class="line"><span>无法完成基本生活事务 · 在非练习时持续幻听幻视</span></span>
<span class="line"><span>确信自己受神灵直接命令 · 出现自伤、伤人或冒险冲动</span></span>
<span class="line"><span>认为自己已不受水火、疾病、交通等现实规律约束</span></span></code></pre></div><p>出现这些情况时，应停止强制修习，恢复正常作息，并及时寻求亲友和专业医疗支持。</p><p><strong>坐忘以「成真」「全生」为目标，不以损害生命为代价。</strong></p><h3 id="完整路线图" tabindex="-1">完整路线图 <a class="header-anchor" href="#完整路线图" aria-label="Permalink to &quot;完整路线图&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定心之上豁然无覆：不受名相、异象与成见遮蔽</span></span>
<span class="line"><span>定心之下旷然无基：不以任何对象、空境或体验为依托</span></span>
<span class="line"><span>        ↓ 上无覆盖，下无攀附 → 无所依著而觉照常明</span></span>
<span class="line"><span>旧业因不再续接而渐消，新业因不以爱恶造作而不生</span></span>
<span class="line"><span>        ↓ 心无缠碍，迥脱名利、声色与人我之网</span></span>
<span class="line"><span>如此行持日久，自然趋向得道</span></span>
<span class="line"><span>        ↓ 在此过程中，心依次经历五时</span></span>
<span class="line"><span>动多静少 → 动静相半 → 静多动少 → 无事则静事触还动 → 心与道合触而不动</span></span>
<span class="line"><span>        ↓ 心至第五时，始得真正安乐；旧有罪垢渐尽</span></span>
<span class="line"><span>心的安定进一步薰养形体，身上逐渐显现七候</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>举动顺时容色和悦 → 夙疾普消身心轻爽 → 填补夭伤还元复命</span></span>
<span class="line"><span>→ 延数千岁名曰仙人 → 炼形为气名曰真人 → 炼气成神名曰神人 → 炼神合道名曰至人</span></span>
<span class="line"><span>        ↓ 随着身心转化逐步深入，鉴照之力也随之增明</span></span>
<span class="line"><span>直到至道成就，智慧才算圆满具足</span></span>
<span class="line"><span>        ↓ 由调心入定，由定自然发慧；由定慧相养，进而薰习形神</span></span>
<span class="line"><span>由形、气、神层层炼化，最终归于大道</span></span>
<span class="line"><span>        ↓ 三戒具足，五时成熟，七候圆备 → 形神俱妙，炼神合道 → 成就至人</span></span></code></pre></div><p>归纳为三个彼此相接的系统：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>修行原则：三戒——简缘、无欲、静心</span></span>
<span class="line"><span>        ↓ 为心创造清静条件</span></span>
<span class="line"><span>心性进程：五时——由动多静少至触而不动</span></span>
<span class="line"><span>        ↓ 心神安定，逐渐薰养并转化形体</span></span>
<span class="line"><span>形神进程：七候——由身心和悦至炼神合道</span></span></code></pre></div><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h3><p>《坐忘枢翼》将《坐忘论》七篇的宏大结构，重新落实为一套极其具体的调心原则。它先告诉我们如何开始（去邪行 → 绝外扰 → 端坐内观 → 念起即觉 → 觉而不续），随后说明怎样避免用力偏差（只灭妄动不灭觉照；需要收时便收却不执著控制；需要放时便放却不随境散逸），再进一步说明定与现实事务的关系（无事时自然安定是体，有事时随缘而应是迹；不主动增加事务），对于智慧与异象则坚持：不可急求智慧，不可追逐异象——定若成熟慧自显发，异象若现知其随心而生、不取不随。</p><p>最后，全篇以「三戒、五时、七候」建立完整进程。<strong>因此，《坐忘枢翼》之「枢」，是三戒与调心中道；其「翼」，则是定慧相养及形神渐化。</strong></p><p>全文最精炼的总纲可以写成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>外简其缘，内寡其欲，中心常静</span></span>
<span class="line"><span>念起即觉，觉而不随</span></span>
<span class="line"><span>制而不著，放而不逸</span></span>
<span class="line"><span>无事安定，有事随应</span></span>
<span class="line"><span>定不求慧，慧生不用</span></span>
<span class="line"><span>见异不取，久久行持</span></span>
<span class="line"><span>心历五时，身显七候</span></span>
<span class="line"><span>最终炼神合道</span></span></code></pre></div><p>它为整部《坐忘论》补上了一个重要的实践结论：</p><blockquote><p><strong>真正的坐忘，既不是强压成空，也不是任心自然；而是在持续觉照中减去攀缘，使心由作意收摄渐至自然安定，由自然安定渐发本慧，并使定慧长期薰养整个形神。</strong></p></blockquote><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/">《坐忘论》总览</a> · <a href="/Dao/daoism/daoist-classics/zuowang-lun/guide">全书引读</a> · <a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">引经据典</a></li><li>上一篇：<a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-07">得道七</a></li><li>引文出处：《道德经》（人能虚心无为，非欲于道，道自归之）</li><li>《天隐子》对应：<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-4">斋戒四</a>、<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-5">安处五</a>、<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-3">渐门三</a>、<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-7">坐忘七</a>、<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-8">神解八</a></li></ul>`,213))])}const q=l(g,[["render",c]]);export{y as __pageData,q as default};
